/**
 * via(): ['twilio'] in a Notification sends it with message_send.
 *
 * The recipient is the notifiable's routeNotificationForTwilio() (Laravel's own
 * convention), sent as 'to'. The notification's toTwilio($notifiable) returns
 * the message: a string (sent as 'body') or message_send's config as an
 * array. No route means nothing is sent, as with Laravel's own channels.
 */
final class TwilioChannel
{
    public function send(object $notifiable, Notification $notification): ?ConnectorResult
    {
        $to = method_exists($notifiable, 'routeNotificationFor')
            ? $notifiable->routeNotificationFor('twilio', $notification)
            : null;
        if ($to === null || $to === '') {
            return null;
        }

        if (! method_exists($notification, 'toTwilio')) {
            throw new LogicException(
                $notification::class.' is sent via twilio and has no toTwilio($notifiable) method returning the message.',
            );
        }
        $message = $notification->toTwilio($notifiable);
        $config = is_string($message) ? ['body' => $message] : (array) $message;

        // config('connectors.<slug>.notifications') fills what the message leaves
        // out (the sender, typically); the message wins.
        $container = Container::getInstance();
        $defaults = array_filter(
            (array) $container->make('config')->get('connectors.twilio.notifications', []),
            static fn ($value): bool => $value !== null && $value !== '',
        );

        return $container->make(TwilioClient::class)->call(
            'message_send',
            ['to' => (string) $to] + $config + $defaults,
        );
    }
}
